function interact(){if(state.active){let o=state.active;let target=o.status==='accepted'?places.find(p=>p.id===o.pickup):o.dest;if(dist(state.player,target)>1.5){showToast(`Chegue mais perto de ${o.status==='accepted'?o.shop:o.customer} para interagir.`);return}if(o.status==='accepted'){o.status='picked';state.inventory['Pedido: '+o.item]=1;state.needs.energy=clamp(state.needs.energy-3);showToast('Pedido retirado! Agora é só chegar ao destino. 📦');renderOrders();return}else{let elapsed=state.minutes-(o.deadline-Math.round((o.dist+2)*5.5));let late=state.minutes>o.deadline;let pay=late?Math.round(o.pay*.68):o.pay;let tip=!late&&elapsed<Math.round((o.dist+2)*2.8)?Math.round(o.pay*.18):0;state.money+=pay+tip;state.dog.love=clamp(state.dog.love+3);state.needs.energy=clamp(state.needs.energy-4);delete state.inventory['Pedido: '+o.item];state.active=null;showToast(late?`Entrega feita! Pagamento reduzido: ${cash(pay)}.`:`Entrega concluída! ${cash(pay)}${tip?' + '+cash(tip)+' de gorjeta!':''} 🎉`);state.orders=state.orders.filter(x=>x.id!==o.id);setTimeout(()=>{if(state.orders.length<3&&!state.active){let n=orderSeeds[Math.floor(Math.random()*orderSeeds.length)];let p=places.find(x=>x.id===n.pickup),c=customers[Math.floor(Math.random()*customers.length)];state.orders.push({...n,id:Date.now(),customer:c.name,dest:{x:c.x,y:c.y},deadline:state.minutes+Math.round((dist(p,c)+2)*5.5),status:'available'});renderOrders()}},4200);updateUI();return}}
let p=nearestPlace();if(!p){showToast('Não há nada por aqui. Explore o bairro!');return}if(p.id==='home'){if(state.inside){state.inside=false;state.player.x=2.8;state.player.y=2.8;showToast('Você saiu de casa. Bom dia, Amora!');updateUI()}else{state.inside=true;state.player.x=5;state.player.y=5;state.dogPos.x=4.5;state.dogPos.y=5;showToast('Você chegou em casa. Amora veio te receber! 🐕');updateUI()}return}if(p.type==='food'||p.type==='market'){openShop();return}if(p.type==='bike'){openBikes();return}if(p.type==='park'){state.needs.energy=clamp(state.needs.energy+10);state.dog.love=clamp(state.dog.love+8);showToast('Uma pausa gostosa na praça. Energia +10, Amora +8. 🌳');updateUI()}}
document.getElementById('zoomIn').onclick=()=>{state.zoom=Math.min(1.35,state.zoom+.1)};document.getElementById('zoomOut').onclick=()=>{state.zoom=Math.max(.75,state.zoom-.1)};
document.getElementById('interactBtn').title='Interagir com o lugar ou concluir uma etapa';
function resize(){let r=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(r.width*dpr);canvas.height=Math.round(r.height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}new ResizeObserver(resize).observe(canvas);resize();
function geometry(){let w=canvas.clientWidth,h=canvas.clientHeight,tw=Math.min(62,w/13)*state.zoom,th=tw*.49;return {w,h,tw,th,ox:w/2,oy:h*.51}}
function project(x,y,g){return {x:g.ox+(x-y)*g.tw/2+state.mapOffset.x,y:g.oy+(x+y-10)*g.th/2+state.mapOffset.y}}
function poly(points,fill,stroke){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke()}}
function ellipse(x,y,rx,ry,color){ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fillStyle=color;ctx.fill()}
function drawTile(x,y,g){let p=project(x,y,g),road=(x>=4&&x<=7)||(y>=4&&y<=6);let c=road?((x+y)%2?'#b8b5a7':'#c1beaf'):((x*7+y*13)%5===0?'#b2d1a7':(x+y)%3===0?'#b9d6ad':'#c4dcb3');poly([{x:p.x,y:p.y-g.th/2},{x:p.x+g.tw/2,y:p.y},{x:p.x,y:p.y+g.th/2},{x:p.x-g.tw/2,y:p.y}],c,road?'#b1b1a3':'#b4ceaa');if(!road&&(x*11+y*3)%9===0){ellipse(p.x-5,p.y-2,2,1.4,'#e2d492');ellipse(p.x+5,p.y+2,1.7,1,'#e0c989')}if(road&&(x===5||x===6)&&y%2===0){ctx.strokeStyle='#e7dfb3';ctx.setLineDash([3,5]);ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(p.x-10,p.y);ctx.lineTo(p.x+10,p.y);ctx.stroke();ctx.setLineDash([])}}
function drawTree(p,g,variant=0){let s=g.tw/62;ellipse(p.x+2*s,p.y+3*s,10*s,4*s,'#63855c55');ctx.fillStyle='#755a40';ctx.fillRect(p.x-2*s,p.y-14*s,4*s,15*s);ellipse(p.x-3*s,p.y-20*s,10*s,9*s,variant?'#66975e':'#55936c');ellipse(p.x+4*s,p.y-23*s,8*s,8*s,variant?'#76a767':'#68a978');ellipse(p.x-2*s,p.y-28*s,7*s,7*s,variant?'#8caf62':'#79b179');if(variant){ellipse(p.x+2*s,p.y-30*s,2*s,2*s,'#f1bd61');ellipse(p.x-5*s,p.y-25*s,2*s,2*s,'#e9ad61')}}
function drawBuilding(pl,g){let p=project(pl.x,pl.y,g),s=g.tw/62,bw=g.tw*.84*pl.w,bh=g.th*1.14*pl.h,ht=g.th*1.65;ellipse(p.x,p.y+2,bw*.75,7*s,'#53685240');let left={x:p.x-bw/2,y:p.y-bh/2},top={x:p.x,y:p.y-bh/2-bh*.42},right={x:p.x+bw/2,y:p.y-bh/2};poly([{x:left.x,y:left.y},{x:p.x,y:p.y+bh*.12},{x:p.x,y:p.y+ht+bh*.12},{x:left.x,y:left.y+ht}],pl.color);poly([{x:p.x,y:p.y+bh*.12},{x:right.x,y:right.y},{x:right.x,y:right.y+ht},{x:p.x,y:p.y+ht+bh*.12}],shade(pl.color,-20));poly([{x:left.x,y:left.y},{x:p.x,y:top.y},{x:right.x,y:right.y},{x:p.x,y:p.y+bh*.12}],shade(pl.color,19));
// awning / facade detail
let door={x:p.x-bw*.03,y:p.y+ht*.56};poly([{x:door.x-7*s,y:door.y},{x:door.x+7*s,y:door.y+4*s},{x:door.x+7*s,y:door.y+ht*.34},{x:door.x-7*s,y:door.y+ht*.30}],'#795b49');poly([{x:p.x+13*s,y:p.y+ht*.44},{x:p.x+26*s,y:p.y+ht*.49},{x:p.x+26*s,y:p.y+ht*.68},{x:p.x+13*s,y:p.y+ht*.63}],'#a9d8d1');poly([{x:p.x+12*s,y:p.y+ht*.41},{x:p.x+27*s,y:p.y+ht*.46},{x:p.x+27*s,y:p.y+ht*.5},{x:p.x+12*s,y:p.y+ht*.45}],shade(pl.color,26));
ctx.fillStyle='#fff9e8';ctx.font=`700 ${Math.max(8,9*s)}px DM Sans`;ctx.textAlign='center';ctx.fillText(pl.name,p.x,p.y-ht-.2*s);ctx.textAlign='start';
}
function shade(hex,amt){let c=hex.replace('#','');let n=parseInt(c,16),r=Math.max(0,Math.min(255,(n>>16)+amt)),gg=Math.max(0,Math.min(255,((n>>8)&255)+amt)),b=Math.max(0,Math.min(255,(n&255)+amt));return `rgb(${r},${gg},${b})`}
function drawInterior(g){let {w,h,tw,th}=g;let bg=ctx.createLinearGradient(0,0,w,h);bg.addColorStop(0,'#e8c99e');bg.addColorStop(1,'#d9b789');ctx.fillStyle=bg;ctx.fillRect(0,0,w,h);let ox=w/2,oy=h*.57;poly([{x:ox,y:oy-4*th},{x:ox+6*tw,y:oy-3*th},{x:ox,y:oy},{x:ox-6*tw,y:oy-3*th}],'#d9c6a9');poly([{x:ox,y:oy-4*th},{x:ox+6*tw,y:oy-3*th},{x:ox+6*tw,y:oy-1.6*th},{x:ox,y:oy-2.7*th}],'#b9795e');poly([{x:ox,y:oy-4*th},{x:ox-6*tw,y:oy-3*th},{x:ox-6*tw,y:oy-1.6*th},{x:ox,y:oy-2.7*th}],'#c98b69');let floor=(x,y)=>({x:ox+(x-y)*tw/2,y:oy-4*th+(x+y)*th/2});for(let x=0;x<5;x++)for(let y=0;y<5;y++){let p=floor(x,y);poly([{x:p.x,y:p.y},{x:p.x+tw/2,y:p.y+th/2},{x:p.x,y:p.y+th},{x:p.x-tw/2,y:p.y+th/2}],(x+y)%2?'#e7d6b9':'#eadbc2','#ddc9aa')}let sofa=floor(1,2);poly([{x:sofa.x-25, y:sofa.y-20},{x:sofa.x+18,y:sofa.y-8},{x:sofa.x+18,y:sofa.y+6},{x:sofa.x-25,y:sofa.y-6}],'#739786');let bed=floor(3,1);poly([{x:bed.x-26,y:bed.y-19},{x:bed.x+15,y:bed.y-7},{x:bed.x+15,y:bed.y+8},{x:bed.x-26,y:bed.y-5}],'#f4eee1');let table=floor(3,3);ellipse(table.x,table.y,22,10,'#a8754d');ctx.fillStyle='#fff4dc';ctx.font='12px DM Sans';ctx.fillText('🏠 Seu lar, seu descanso',w/2-78,30);ctx.font='18px sans-serif';ctx.fillText('🌱',floor(0,1).x,floor(0,1).y-5);ctx.fillText('🪴',floor(4,2).x,floor(4,2).y-10);}
function drawBikeRider(x,y,g,frame){let s=g.tw/62;ellipse(x,y+5*s,13*s,4*s,'#183b3540');let roll=Math.sin(frame*10)*1.5*s;ctx.strokeStyle='#273d39';ctx.lineWidth=1.6*s;ctx.beginPath();ctx.arc(x-7*s,y+1*s,6*s,0,Math.PI*2);ctx.arc(x+8*s,y+1*s,6*s,0,Math.PI*2);ctx.stroke();ctx.beginPath();ctx.moveTo(x-7*s,y+1*s);ctx.lineTo(x,y-4*s+roll);ctx.lineTo(x+8*s,y+1*s);ctx.lineTo(x+1*s,y+1*s);ctx.lineTo(x-7*s,y+1*s);ctx.moveTo(x,y-4*s+roll);ctx.lineTo(x+2*s,y-9*s+roll);ctx.lineTo(x+7*s,y-9*s+roll);ctx.moveTo(x,y-4*s+roll);ctx.lineTo(x-3*s,y-9*s+roll);ctx.stroke();ellipse(x+1*s,y-13*s+roll,4*s,4*s,'#50372c');ctx.strokeStyle='#376a56';ctx.lineWidth=5*s;ctx.beginPath();ctx.moveTo(x,y-9*s+roll);ctx.lineTo(x-1*s,y-2*s+roll);ctx.lineTo(x+5*s,y-5*s+roll);ctx.stroke();ctx.strokeStyle='#d5a180';ctx.lineWidth=2*s;ctx.beginPath();ctx.moveTo(x+4*s,y-7*s+roll);ctx.lineTo(x+7*s,y-9*s+roll);ctx.stroke()}
function drawDog(x,y,g,frame){let s=g.tw/62,sc=1+Math.sin(frame*5)*.035;ellipse(x,y+4*s,9*s,3*s,'#433b3340');ellipse(x,y-2*s,9*s*sc,5*s*sc,'#b77746');ellipse(x+6*s,y-5*s,5*s,5*s,'#c68652');ellipse(x+3*s,y-9*s,2*s,4*s,'#794b37');ellipse(x+9*s,y-9*s,2*s,4*s,'#794b37');ellipse(x+8*s,y-5*s,1*s,1*s,'#282521');ellipse(x+12*s,y-3*s,1.5*s,1*s,'#30241d');ctx.strokeStyle='#754b35';ctx.lineWidth=1.4*s;ctx.beginPath();ctx.moveTo(x-7*s,y-4*s);ctx.quadraticCurveTo(x-14*s,y-9*s,x-10*s,y-12*s+Math.sin(frame*7)*2);ctx.stroke()}

