function drawScene(now){const g=geometry(),{w,h,tw,th}=g;ctx.clearRect(0,0,w,h);let night=state.minutes>=19*60||state.minutes<6*60;let sky=ctx.createLinearGradient(0,0,0,h);sky.addColorStop(0,night?'#53677b':'#9bc7c3');sky.addColorStop(.64,night?'#9ba6a2':'#d5e4bd');sky.addColorStop(1,night?'#b4b1a0':'#d5dfb7');ctx.fillStyle=sky;ctx.fillRect(0,0,w,h);
// soft neighborhood backdrop
for(let i=0;i<7;i++){let x=(i*173+42)%w,y=75+(i%3)*49;ellipse(x,y,45,17,night?'#ffffff0d':'#fff8df55')}
if(state.inside){drawInterior(g);let x=w/2+((state.player.x-state.player.y)*tw/2),y=h*.57-4*th+((state.player.x+state.player.y)*th/2);drawBikeRider(x,y,g,now/1000);let dx=x-26,dy=y+12;drawDog(dx,dy,g,now/1000);ctx.fillStyle='#fff9e8';ctx.font=`700 10px DM Sans`;ctx.textAlign='center';ctx.fillText('Lia',x,y-24);ctx.textAlign='start';return}
for(let y=0;y<11;y++)for(let x=0;x<12;x++)drawTile(x,y,g);
// decorative trees on green lots
[[0,1],[1,4],[0,8],[4,1],[8,1],[8,7],[11,8],[5,10],[2,9],[7,7],[11,4],[0,6]].forEach((a,i)=>{let p=project(a[0],a[1],g);drawTree(p,g,i%4===0)});
// bicycles at the workshop and small street details
let workshop=project(10,2,g);ellipse(workshop.x-28,workshop.y+4,8,3,'#485d4c55');ctx.strokeStyle='#405d54';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(workshop.x-29,workshop.y,4,0,Math.PI*2);ctx.arc(workshop.x-18,workshop.y,4,0,Math.PI*2);ctx.moveTo(workshop.x-29,workshop.y);ctx.lineTo(workshop.x-23,workshop.y-5);ctx.lineTo(workshop.x-18,workshop.y);ctx.stroke();
let sorted=[...places].sort((a,b)=>(a.x+a.y)-(b.x+b.y));sorted.forEach(pl=>drawBuilding(pl,g));
// delivery route and target marker
if(state.active){let target=state.active.status==='accepted'?places.find(p=>p.id===state.active.pickup):state.active.dest;let start=project(state.player.x,state.player.y,g),end=project(target.x,target.y,g);ctx.save();ctx.setLineDash([6,5]);ctx.strokeStyle='#fff7d4';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(start.x,start.y);ctx.lineTo(end.x,end.y);ctx.stroke();ctx.restore();let pulse=1+Math.sin(now/240)*.13;ellipse(end.x,end.y-19,13*pulse,13*pulse,'#fff5cfdd');ctx.fillStyle='#286b50';ctx.font='bold 14px sans-serif';ctx.textAlign='center';ctx.fillText(state.active.status==='accepted'?'📦':'📍',end.x,end.y-14);ctx.textAlign='start'}
// player, companion, shadow and name
let pp=project(state.player.x,state.player.y,g);drawBikeRider(pp.x,pp.y,g,now/1000);ctx.textAlign='center';ctx.font=`700 ${Math.max(9,10*tw/62)}px DM Sans`;ctx.fillStyle='#fff9ec';ctx.fillText('Lia',pp.x,pp.y-25*tw/62);ctx.textAlign='start';
let dog=state.dogPos,dp=project(dog.x,dog.y,g);drawDog(dp.x,dp.y,g,now/1000);
// light overlay at dusk
if(night){ctx.fillStyle='#1b2a4650';ctx.fillRect(0,0,w,h);let gl=ctx.createRadialGradient(pp.x,pp.y,5,pp.x,pp.y,155);gl.addColorStop(0,'#ffe9a222');gl.addColorStop(1,'#18273c00');ctx.fillStyle=gl;ctx.fillRect(0,0,w,h);for(let i=0;i<12;i++){let p=project((i*7)%12,(i*5)%11,g);ctx.fillStyle='#ffe9ad';ctx.fillRect(p.x,p.y-25,2,2)}}
if(state.weather==='rain'){ctx.strokeStyle='#e8f5f5a0';ctx.lineWidth=1;for(let i=0;i<70;i++){let x=(i*89+now*.08)%w,y=(i*47+now*.18)%h;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-4,y+9);ctx.stroke()}}
// vignette gives the map depth
let v=ctx.createRadialGradient(w/2,h/2,80,w/2,h/2,Math.max(w,h)*.69);v.addColorStop(.65,'#193d2d00');v.addColorStop(1,'#193d2d24');ctx.fillStyle=v;ctx.fillRect(0,0,w,h)
}
function worldFromScreen(px,py){let g=geometry(),a=(px-g.ox-state.mapOffset.x)*2/g.tw,b=(py-g.oy-state.mapOffset.y)*2/g.th;return {x:(a+b+10)/2,y:(b-a+10)/2}}
canvas.addEventListener('pointerdown',e=>{let r=canvas.getBoundingClientRect(),p=worldFromScreen(e.clientX-r.left,e.clientY-r.top);if(!state.inside){state.player.x=clamp(p.x,0,11.8);state.player.y=clamp(p.y,0,10.8);state.needs.energy=clamp(state.needs.energy-.35);state.player.step+=1;updateUI()} });
function setMove(x,y){state.move={x,y}}
