 <script>
+(()=>{'use strict';
+const $=s=>document.querySelector(s),canvas=$('#game'),ctx=canvas.getContext('2d');
+const S={money:38.5,day:1,min:500,weather:'sun',p:{x:5.2,y:5.1},dog:{x:4.7,y:5.4,h:70,t:83,l:76},need:{hunger:84,thirst:91,sleep:78,energy:88},bike:0,inside:false,active:null,bag:{'Pão de queijo':1,'Garrafa d’água':1},move:{x:0,y:0},zoom:1};
+const bikes=[['Caloi da Nanda',0,5,'Emprestada · simples, mas de confiança'],['BMX básica',350,7,'Ágil e resistente · sua primeira conquista!'],['BMX turbinada',680,8,'Mais leve, rápida e pronta pra qualquer rua.'],['Urbana conforto',950,7,'Pedalada suave e eficiente.'],['Pro entregadora',1600,10,'Equipamento profissional. A cidade é sua.']];
+const places=[{id:'home',name:'Casa da Lia',desc:'Seu cantinho e o lar da Amora',x:2,y:2,type:'home',c:'#e7a873',icon:'🏠'},{id:'cafe',name:'Café da Esquina',desc:'Café coado e pão de queijo quentinho',x:8,y:2,type:'shop',c:'#d57958',icon:'☕'},{id:'market',name:'Mercadinho Sol',desc:'Tudo que falta pra despensa',x:10,y:6,type:'shop',c:'#d6ad51',icon:'🛒'},{id:'park',name:'Praça do Ipê',desc:'Sombra boa e espaço pra respirar',x:3,y:7,type:'park',c:'#5d9c69',icon:'🌳'},{id:'food',name:'Tempero da Vó',desc:'Almoço caseiro feito com carinho',x:6,y:9,type:'shop',c:'#c76e53',icon:'🍲'},{id:'bike',name:'Oficina Pedal Forte',desc:'Sua próxima bicicleta está aqui',x:10,y:2,type:'bike',c:'#5f8c9b',icon:'🔧'}];
+const customers=[['Apê da Bia',2,5],['Seu Raul',7,5],['Ateliê Flor de Rua',9,8],['Casa amarela',4,3],['Dona Cida',1,9]],seeds=[['Café da Esquina','cafe','2 cafés + pão na chapa',24],['Mercadinho Sol','market','Comprinhas da semana',36],['Tempero da Vó','food','Marmita de frango',32],['Café da Esquina','cafe','Bolo de fubá',28],['Mercadinho Sol','market','Frutas fresquinhas',31]];
+const cash=n=>'R$ '+n.toFixed(2).replace('.',','),clamp=(n,a=0,b=100)=>Math.max(a,Math.min(b,n)),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y),time=()=>`${String(Math.floor(S.min/60)%24).padStart(2,'0')}:${String(S.min%60).padStart(2,'0')}`,fmt=d=>(d*.12).toFixed(1).replace('.',',')+' km';
+function toast(t){let e=$('#toast');e.textContent=t;e.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.classList.remove('show'),2500)}
+function genOrders(){S.orders=seeds.slice(0,3).map((a,i)=>{let c=customers[(S.day+i)%customers.length],d=places.find(p=>p.id===a[1]);return {id:S.day+'-'+i,shop:a[0],pickup:a[1],item:a[2],pay:a[3],customer:c[0],dest:{x:c[1],y:c[2]},deadline:S.min+Math.round((dist(d,{x:c[1],y:c[2]})+2)*5.5),status:'available'}});renderOrders()}
+function near(){let p=null,d=99;places.forEach(q=>{let n=dist(S.p,q);if(n<d){p=q;d=n}});return d<1.6?p:null}
+function renderOrders(){let el=$('#orders');if(!el)return;if(S.active){let o=S.active,pick=o.status==='accepted',target=pick?places.find(p=>p.id===o.pickup):o.dest;el.innerHTML=`<div class="order active-order"><div class="order-top"><b>${pick?'📦 Retirada':'🏁 Entrega'} · ${o.shop}</b><span class="reward">${cash(o.pay)}</span></div><div class="order-sub">${o.item} → ${o.customer}</div><div class="order-meta"><span>📍 ${pick?o.shop:o.customer} · ${fmt(dist(S.p,target))}</span><span>⏱ ${Math.max(0,o.deadline-S.min)} min</span></div><div class="order-status">● ${pick?'Vá buscar seu pedido':'Pedido na bolsa — bora entregar!'}</div><div class="active-actions" style="margin-top:9px"><button class="btn btn-quiet" id="navTarget">📍 Marcar no mapa</button><button class="btn btn-danger" id="cancelOrder">Recusar</button></div></div>`;$('#navTarget').onclick=()=>toast('Destino marcado no mapa!');$('#cancelOrder').onclick=()=>{S.active=null;toast('Pedido recusado. Sem problema!');renderOrders()};$('#orderCount').textContent='1 em andamento';return}let list=(S.orders||[]).filter(o=>o.status==='available');$('#orderCount').textContent=list.length+' disponíveis';el.innerHTML=list.length?list.map(o=>`<div class="order"><div class="order-top"><b>${o.shop}</b><span class="reward">${cash(o.pay)}</span></div><div class="order-sub">${o.item} → ${o.customer}</div><div class="order-meta"><span>📍 ${fmt(dist(places.find(p=>p.id===o.pickup),o.dest))}</span><span>⏱ até ${time()}</span></div><button class="btn btn-primary accept" data-id="${o.id}">Aceitar entrega</button></div>`).join(''):'<div class="empty-orders">Nenhum chamado por enquanto.<br>Daqui a pouco aparece outro! 🛎️</div>';el.querySelectorAll('.accept').forEach(b=>b.onclick=()=>accept(b.dataset.id))}
+function accept(id){if(S.active)return toast('Finalize sua entrega atual primeiro!');let o=S.orders.find(x=>x.id===id);if(o){S.active={...o,status:'accepted'};toast('Pedido aceito! Busque em '+o.shop+'.');renderOrders()}}
+function ui(){let m=$('#money');if(!m)return;m.textContent=cash(S.money);$('#clock').textContent=time();$('#dayNum').textContent=S.day;Object.entries(S.need).forEach(([k,v])=>{$('#'+k+'Num').textContent=Math.round(v)+'%';$('#'+k+'Bar').style.width=v+'%';$('#'+k+'Bar').parentElement.classList.toggle('red',v<25)});$('#goalBar').style.width=Math.min(100,S.money/3.5)+'%';$('#goalText').textContent=cash(Math.min(S.money,350))+' / R$ 350';['h','t','l'].forEach((k,i)=>$('#dog'+['Hunger','Thirst','Love'][i]+'Bar').style.width=S.dog[k]+'%');$('#dogAttention').textContent='♥ '+Math.round(S.dog.l);$('#dogMood').textContent=S.dog.h<30?'Amora está com fome 🥺':'Está feliz por estar com você';$('#bikeName').textContent=bikes[S.bike][0];$('#bikeCondition').textContent=bikes[S.bike][3];$('#bikeSpeed').textContent='Vel. '+bikes[S.bike][2];$('#inventoryCount').textContent=Object.values(S.bag).reduce((a,b)=>a+b,0)+' itens';let dark=S.min>1140||S.min<360;$('#weatherIcon').textContent=S.weather==='rain'?'🌧️':dark?'🌙':'☀️';$('#weatherLabel').textContent=S.weather==='rain'?'Chuvoso':dark?'Noite':'Ensolarado';$('#weatherHint').textContent=S.weather==='rain'?'🌧 Chuva fina na cidade':dark?'🌙 A cidade desacelera':'☀ Dia bom pra pedalar';let p=near();$('#interactLabel').textContent=p?p.name:'Perto de você';$('#locationName').textContent=S.inside?'Casa da Lia':p?p.name:'Vila das Mangueiras';$('#locationDesc').textContent=S.inside?'Lar doce lar · Amora está por aqui':p?p.desc:'Um bairro cheio de histórias';renderOrders()}
+genOrders();

