function buy(name,price,kind){if(S.money<price)return toast('Ainda falta um pouquinho de dinheiro.');S.money-=price;if(kind==='food'||kind==='water'){S.bag[name]=(S.bag[name]||0)+1;toast(name+' guardado na bolsa!')}else{S.need[kind]=clamp(S.need[kind]+(kind==='sleep'?0:35));toast('Você se sente melhor!')}ui();save()}
